import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as t,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Gemini Code Assist","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/code-assist.md","filePath":"zh/products/ai-coding/gemini/code-assist.md","lastUpdated":1787042982000}'),n={name:"zh/products/ai-coding/gemini/code-assist.md"};function r(l,s,o,h,d,p){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="gemini-code-assist" tabindex="-1">Gemini Code Assist <a class="header-anchor" href="#gemini-code-assist" aria-label="Permalink to &quot;Gemini Code Assist&quot;">​</a></h1><blockquote><p>Google 的 IDE 集成扩展。家族里唯一以<strong>企业合规</strong>为主要卖点的编码产品。</p></blockquote><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><p>自主智能体是趋势，但开发者大量时间仍然在 VS Code 或 JetBrains 里。Code Assist 补的是这一块：不要求你换工具、换工作流，代价是它的上下文边界也就限于编辑器能看到的范围。</p><p>支持的 IDE：VS Code、JetBrains 系列、Android Studio。</p><h2 id="三个版本" tabindex="-1">三个版本 <a class="header-anchor" href="#三个版本" aria-label="Permalink to &quot;三个版本&quot;">​</a></h2><p>官方提供 free / Standard / Enterprise 三个版本。<strong>能力绑在版本上，不绑在你的个人 Google AI 订阅上</strong>——买了个人 AI Pro 不会让 Code Assist 变成企业版。</p><p><strong>2026-06-18 起，面向个人的 free 档以及 Google AI Pro / Ultra 通过「Login with Google」访问 IDE 扩展已停服。</strong> 个人开发者请改用 <a href="./antigravity.html">Antigravity</a> 的 IDE / CLI 表面。Standard / Enterprise 许可证不受影响。<a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">官方弃用说明</a>。</p><p>企业版本的卖点是合规而不是更聪明。官方文档开场就写给&quot;有严格数据安全与合规要求的组织&quot;，明确提供：</p><ul><li>VPC Service Controls</li><li>知识产权赔偿（IP indemnification）</li></ul><p>如果你的团队正因为合规原因不能用其他 AI 编码工具，这是家族里该看的那一个。</p><p>模型方面，官方文档标注 Code Assist 使用 Gemini 2.5 模型。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>代码补全与生成</td><td>编辑器内的主要交互形态</td></tr><tr><td>智能体模式</td><td>能理解代码库上下文并执行多步改动</td></tr><tr><td>MCP 支持</td><td>可以接外部工具</td></tr><tr><td>Gemini CLI 额度</td><td>订阅包含 Gemini CLI 的使用额度</td></tr></tbody></table><blockquote><p>⚠️ 历史版本文档里出现过这样一段配置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;codeAssist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agentMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;autoApprove&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><p><strong>官方文档里不存在这个 JSON 配置键。</strong> 智能体模式确实存在，但开启方式请以官方文档为准，不要照抄这段。</p></blockquote><h2 id="用法要点" tabindex="-1">用法要点 <a class="header-anchor" href="#用法要点" aria-label="Permalink to &quot;用法要点&quot;">​</a></h2><h3 id="规范先行" tabindex="-1">规范先行 <a class="header-anchor" href="#规范先行" aria-label="Permalink to &quot;规范先行&quot;">​</a></h3><p>不要抛一个模糊想法就期待完美产出。让它先产出规范，再按规范生成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 用对话生成 spec.md</span></span>
<span class="line"><span>   → 接口约束、Props 定义、状态管理策略、边缘情况</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 把 spec.md 作为上下文输入</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 按规范逐步生成代码</span></span></code></pre></div><p>这么做的实际收益是<strong>防止长对话里的架构漂移</strong>。有一份写下来的规范在上下文里，模型每一步都有锚点；没有的话它会慢慢偏离你最初的意图，而且偏离得很难察觉。</p><h3 id="配合-gemini-cli-排错" tabindex="-1">配合 Gemini CLI 排错 <a class="header-anchor" href="#配合-gemini-cli-排错" aria-label="Permalink to &quot;配合 Gemini CLI 排错&quot;">​</a></h3><p>编辑器里看报错不如把日志直接喂过去：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;分析构建错误，给出最小修复&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;按根因分组这些类型错误&quot;</span></span></code></pre></div><p>分工是清楚的：<strong>终端里的事交给 <a href="./gemini-cli.html">Gemini CLI</a>，编辑器里的事交给 Code Assist。</strong></p><h2 id="常见问题-跨仓库时的上下文幻觉" tabindex="-1">常见问题：跨仓库时的上下文幻觉 <a class="header-anchor" href="#常见问题-跨仓库时的上下文幻觉" aria-label="Permalink to &quot;常见问题：跨仓库时的上下文幻觉&quot;">​</a></h2><p><strong>现象</strong>：生成跨微前端 / 跨服务的逻辑时，它开始编 API 契约。</p><p><strong>原因</strong>：IDE 插件的上下文受限于当前打开的文件和本地索引的工作区。如果你的前端依赖一个没在本地索引的后端仓库里的类型定义，模型看不到，只能猜。</p><p><strong>解决</strong>：</p><ol><li>把相关的接口契约和类型定义文件拉进当前工作区</li><li>选中这些内容，明确让它纳入上下文</li></ol><p><strong>根本判断</strong>：如果一个任务必须同时理解多个仓库，Code Assist 就不是合适的工具。这种情况该用能自己去读的 <a href="./antigravity.html">Antigravity</a>。</p><h2 id="与其他产品怎么选" tabindex="-1">与其他产品怎么选 <a class="header-anchor" href="#与其他产品怎么选" aria-label="Permalink to &quot;与其他产品怎么选&quot;">​</a></h2><p>完整对比表见 <a href="./gemini-cheatsheet.html#antigravity-vs-code-assist-vs-jules">速查表</a>，本页不重复。</p><p>按&quot;改动范围&quot;记最简单：</p><table tabindex="0"><thead><tr><th>范围</th><th>用</th></tr></thead><tbody><tr><td>终端里执行、排错</td><td><a href="./gemini-cli.html">Gemini CLI</a></td></tr><tr><td>编辑器里补全、单文件到局部多文件</td><td>Code Assist</td></tr><tr><td>跨模块、需要自己去读代码</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td>丢出去等 PR</td><td><a href="./jules.html">Jules</a></td></tr></tbody></table><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://developers.google.com/gemini-code-assist/docs/overview" target="_blank" rel="noreferrer">Code Assist 概览</a></li><li><a href="https://developers.google.com/gemini-code-assist/docs/write-code-gemini" target="_blank" rel="noreferrer">用 Gemini 写代码</a></li><li><a href="https://codeassist.google" target="_blank" rel="noreferrer">产品页</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">速查表</a> — 跨产品决策表</li><li><a href="./gemini-cookbook.html#_15-团队有数据合规要求">Cookbook</a> — 合规场景配方</li></ul>`,38)])])}const b=i(n,[["render",r]]);export{m as __pageData,b as default};
